('maintenance.index'); Route::get('/manutencoes/nova',[OperationsController::class,'maintenanceCreate'])->name('maintenance.create'); Route::post('/manutencoes',[OperationsController::class,'maintenanceStore'])->name('maintenance.store'); Route::get('/relatorios',[ReportsController::class,'index'])->name('reports.index'); Route::get('/relatorios/pdf',[ReportsController::class,'pdf'])->name('reports.pdf'); });
